# Python
class Animal:
    def __init__(self, name):
        self.name = name
    def speak(self):
        return "..."

class Dog(Animal):    # inherits Animal
    def speak(self):
        return "Woof!"

d = Dog("Rex")
print(d.name)     # Rex
print(d.speak())  # Woof!

# Python — clean, readable, slow for CPU work
def fibonacci(n):
    if n <= 1: return n
    return fibonacci(n-1) + fibonacci(n-2)

// C — fastest, manual everything
int fibonacci(int n) {
    if (n <= 1) return n;
    return fibonacci(n-1) + fibonacci(n-2);
}
